    bio: "涿州人，后周殿前都点检。960年陈桥驿“黄袍加身”，兵不血刃代周建宋。用赵普之谋“杯酒释兵权”，以文臣知州、设枢密院、更戍法，终结了武人乱政的两百年。灭荆南、湖南、后蜀、南汉、南唐，“卧榻之侧，岂容他人鼾睡”。976年“烛影斧声”中暴崩，成千古之谜。",
