    desc: "辽承天太后萧燕燕与圣宗率二十万大军南下，深入宋境千里，兵锋直抵澶州（今濮阳），汴京震动。寇准力请真宗亲征，“陛下不过河，则人心益危”。真宗黄龙旗登城，宋军士气大振，伏弩射杀辽将萧挞凛。辽求和，宋岁输银十万两、绢二十万匹。",
