    bio: "江西德安人，安江农校教师。1964年起研究杂交水稻，1973年实现三系配套，使水稻单产大幅提高，此后超级稻亩产不断刷新纪录。一生“禾下乘凉梦”“覆盖全球梦”，养活了数以亿计的人口。2019年获“共和国勋章”，2021年5月22日逝世，长沙市民夹道送别，“袁爷爷，一路走好”。",
