    bio: "辽宁绥中人，空军飞行员出身，中国人民解放军航天员大队航天员。2003年10月15日乘神舟五号飞船进入太空，绕地球14圈、飞行21小时23分，成为进入太空的中国第一人，中国成为继俄美之后第三个独立实现载人航天的国家。着陆后嘴角带血仍微笑挥手，事后透露火箭上升阶段曾经历26秒共振的生死考验。",
    events: ["shenzhou"]
