    bio: "江苏青浦人（今属上海），商务印书馆学徒出身，遵义会议支持毛泽东。长期主持财经工作，“一五”计划、统购统销的主要设计者。文革后与邓小平共同推动拨乱反正与改革开放，主张“摸着石头过河”。中共八大后即为政治局常委，党内经济工作公认的权威。",
    events: ["sanzhong-quanhui"]
