Object.assign(PEOPLE, {
  "huangyueying": {
    name: "黄月英", life: "三国时期", faction: "sanguo", title: "诸葛亮之妻 · 才女",
    bio: "沔阳名士黄承彦之女。《襄阳记》载，黄承彦对诸葛亮说：“闻君择妇；身有丑女，黄头黑色，而才堪相配。”诸葛亮应允迎娶，乡里谚曰“莫作孔明择妇，正得阿承丑女”。民间传说她心灵手巧，木牛流马、诸葛连弩的巧思皆得其启发，是古代传奇才女的典型形象。",
    events: []
  },
  "xiaoqiao": {
    name: "小乔", life: "三国时期", faction: "sanguo", title: "周瑜之妻 · 江东二乔",
    bio: "庐江皖县人，桥公次女（后世作“乔”）。建安四年（199年）孙策攻破皖城，与姐姐大乔一同出嫁——孙策纳大乔、周瑜纳小桥，留下“姐妹共嫁英雄”的佳话。苏轼《念奴娇》“小乔初嫁了，雄姿英发”使她的名字与赤壁的火光永远连在一起。与周瑜相伴十一年，瑜卒，恸哭成疾。",
    events: []
  },
  "caopi": {
    name: "曹丕", life: "187—226", faction: "sanguo", title: "魏文帝 · 典论作者",
    bio: "曹操次子，八岁能文，建安文学的实际召集人。220年曹操去世后继魏王位，同年十月接受汉献帝“禅让”，代汉建魏——延续四百余年的汉家天下正式终结。他推行九品中正制，著《典论·论文》开文学批评先河：“盖文章，经国之大业，不朽之盛事。”与弟曹植的世子之争、“煮豆燃萁”的故事流传千古。",
    events: ["caopi-chanhan"]
  },
  "caozhi": {
    name: "曹植", life: "192—232", faction: "sanguo", title: "才高八斗 · 陈思王",
    bio: "曹操第四子，十岁余即诵读诗论辞赋数十万言，深得曹操宠爱，一度几乎被立为世子。因任性而行、饮酒不节渐失父心。曹丕称帝后备受猜忌，《世说新语》记其七步成诗：“本是同根生，相煎何太急！”后期徙封多地、形同囚禁，41岁郁郁而终。谢灵运评：“天下才有一石，曹子建独占八斗。”",
    events: []
  },
  "simashi": {
    name: "司马师", life: "208—255", faction: "sanguo", title: "晋景帝",
    bio: "司马懿长子，沉着有雄才大略。高平陵之变中亲率兵士封锁司马门，控制京师，是政变成功的关键。司马懿死后继掌魏国大权，废魏帝曹芳、平淮南毌丘俭之乱，行军途中眼疾发作，眼球迸出，痛死于许昌，年48岁。",
    events: ["gaopingling"]
  },
  "simazhao": {
    name: "司马昭", life: "211—265", faction: "sanguo", title: "晋文帝 · 司马昭之心",
    bio: "司马懿次子。兄长司马师死后总揽朝政，263年遣钟会、邓艾三路伐蜀灭汉，进爵晋王。“司马昭之心，路人所知也”——魏帝曹髦率宫卫讨伐，反被其党羽成济当街弑杀，开臣子弑君之恶例。265年病逝，数月后其子司马炎代魏称帝，追尊为文帝。",
    events: ["gaopingling", "sangu-guijin"]
  },
  "zhangsun_huanghou": {
    name: "长孙皇后", life: "601—636", faction: "suitang", title: "一代贤后",
    bio: "河南洛阳人，北魏宗室之后，13岁嫁李世民。玄武门之变当日亲至玄武门激励将士。册立皇后后不干外政，却屡屡在关键时刻护佑直臣：魏征犯颜直谏惹得太宗喊“会须杀此田舍翁”，她换上朝服郑重下拜：“主明臣直。妾向闻陛下礼重魏征，今日方知其实。”我佛也难断的家事，被她化成了治国的美谈。史称“贤后”典范。",
    events: ["xuanwumen"]
  },
  "lizhi": {
    name: "李治（唐高宗）", life: "628—683", faction: "suitang", title: "唐高宗",
    bio: "唐太宗第九子，生性仁弱。649年即位后，勤于政事、灭西突厥与高句丽，唐疆域在其朝达到极盛；但他把宫中旧日的“武才人”迎回宫中，立为皇后——从此“二圣临朝”，为其后武则天称帝埋下伏笔。683年去世，遗诏“军国大事有不决者，兼取天后进止”。",
    events: ["wuzetian"]
  },
  "duguoqieluo": {
    name: "独孤伽罗", life: "544—602", faction: "suitang", title: "隋文献皇后",
    bio: "独孤信之女，14岁嫁杨坚，夫妻誓无异生之子，“誓无异生之子”。杨坚代周建隋的决断，她是最关键的推动者：“大事已然，骑虎之势，必不得下，勉之！”开皇年间她与文帝并称“二圣”，政见常相一致。她主导废黜长子杨勇、改立杨广——这一步棋，最终改写了隋朝的命运。",
    events: ["suitang-tongyi"]
  },
  "mahuanghou": {
    name: "马皇后", life: "1332—1382", faction: "mingdyn", title: "大明孝慈高皇后",
    bio: "宿州人，红巾军首领郭子兴养女，嫁朱元璋为妻。朱元璋被郭子兴猜忌囚禁断食，她怀揣炊饼贴身送去，胸口烫伤；行军中“负太子奔逃”，士卒感念。建国后她贵为皇后却亲自主管宫中膳衾，劝朱元璋少杀戮：“陛下不忘妾同贫贱，愿无忘群臣同艰难。”1382年病逝，此后朱元璋再未立后。",
    events: ["ming-kaiguo"]
  },
  "yongzheng": {
    name: "雍正帝胤禛", life: "1678—1735", faction: "houjin", title: "承上启下的改革皇帝",
    bio: "康熙第四子，45岁在“九子夺嫡”中胜出即位。在位十三年几乎不辍：设军机处强化皇权，行摊丁入亩（人头税并入地税）、火耗归公（整顿吏治）、改土归流（西南设府县），大刀阔斧清查亏空——“雍正一朝，无官不清”。传位乾隆，把一个府库充盈、吏治整肃的帝国交到下一代手中。野史“传位十四子改于四子”纯属附会。",
    events: ["junjichu"]
  },
  "yueyun": {
    name: "岳云", life: "1119—1142", faction: "songdyn", title: "岳家长子 · 赢官人",
    bio: "岳飞长子，12岁即从军，隶张宪部，手持八十斤（一说四十公斤）铁锥枪，冲锋在前，人称“赢官人”。随州、颍昌诸役屡立头功，郾城之战大破金军拐子马。岳飞治军至严，凡有功多隐不报，云毫无怨言。1142年与父亲、部将张宪同日被害于风波亭畔，年仅23岁——中国历史上最令人痛惜的将门之殇。",
    events: ["yuefei"]
  },
  "suxun": {
    name: "苏洵", life: "1009—1066", faction: "wenwu", title: "三苏之父 · 《六国论》",
    bio: "眉州眉山人，27岁才发愤读书，十年而文章名动天下，是“大器晚成”的典范。带二子进京，一篇《权书》（含《六国论》）“六国破灭，非兵不利，战不善，弊在赂秦”借古讽今，震动朝野。“唐宋八大家”中，苏家一门独占三席，天下文章尽出苏门。",
    events: []
  },
  "suzhe": {
    name: "苏辙", life: "1039—1112", faction: "wenwu", title: "小苏 · 颍滨遗老",
    bio: "苏轼之弟，兄弟同榜进士，苏轼一生“但愿人长久，千里共婵娟”即为怀念他而作。与兄同反新法，一生宦海起伏相随，乌台诗案中上书愿以官职赎兄罪。晚年退居许昌颍滨，自称“颍滨遗老”，著《栾城集》。为人沉静简洁，与兄长的豪放恰成对照。",
    events: ["xining"]
  },
  "wangxianzhi": {
    name: "王献之", life: "344—386", faction: "wenwu", title: "小圣 · 一笔书",
    bio: "王羲之第七子，与其父并称“二王”。七八岁时习书，父在其字后抽笔不脱，叹“此儿后当复有大名”。变古制今、创“一笔书”，《中秋帖》《鸭头丸帖》为传世名迹，与《快雪时晴帖》并称“三希”。官至中书令，早逝，年43岁。",
    events: []
  },
  "songmeiling": {
    name: "宋美龄", life: "1898—2003", faction: "gmd", title: "民国第一夫人",
    bio: "海南文昌人，宋庆龄之妹，幼年赴美受教育，毕业于卫斯理学院。1927年与蒋介石结婚，此后长期活跃于外交舞台：西安事变中亲赴西安参与谈判、促成事变和平解决；抗战中以航空委员会秘书长组建“飞虎队”，1943年在美国国会演讲，是首位在美国国会演讲的中国人。《时代》周刊多次以她与蒋介石为封面人物。2003年卒于美国，享年106岁。",
    events: ["xianbian"]
  },
  "xiaofengxian": {
    name: "小凤仙", life: "约1900—1954", faction: "wenhua", title: "侠妓 · 助蔡锷出京",
    bio: "杭州人，家道中落流入风尘，为北京八大胡同云吉班名妓。1915年蔡锷被袁世凯软禁在京，佯装沉迷歌场，与小凤仙相交，借其掩护金蝉脱壳、辗转回到云南，首举护国讨袁义旗。蔡锷病逝后她从此隐没，晚年嫁沈阳一锅炉工为妻，1954年病逝。电影《知音》“高山流水觅知音”唱的正是这段传奇。",
    events: ["huguo"]
  },
  "zhaomingcheng": {
    name: "赵明诚", life: "1081—1129", faction: "wenwu", title: "金石学家 · 李清照之夫",
    bio: "密州诸城人，宰相赵挺之之子，太学生出身，金石学家。与李清照“赌书泼茶”的恩爱为后世艳羡，夫妇共治金石书画，立志撰《金石录》三十卷。靖康之变后南渡，1129年病逝于建康，李清照携残卷颠沛流离，“物是人非事事休，欲语泪先流”——半部《金石录》后半生。",
    events: []
  },
  "xiaozhuang": {
    name: "孝庄文皇后", life: "1613—1688", faction: "houjin", title: "清初三朝的蒙古女杰",
    bio: "科尔沁蒙古博尔济吉特氏，名布木布泰，13岁嫁皇太极，封庄妃。皇太极暴卒后，她联合多尔衮拥立六岁的儿子福临（顺治）即位，稳定了险些内讧的满洲政局；顺治早逝又辅立八岁的孙子康熙，悉心教养、密赞机务，却终身不垂帘、不干政。“太后下嫁多尔衮”为历史悬案。辅佐三代帝王，是中国历史上最杰出的女政治家之一。",
    events: []
  },

  /* ---------- 毛泽东家族 ---------- */
  "yangkaihui": {
    name: "杨开慧", life: "1901—1930", faction: "ccp", title: "毛泽东夫人 · 革命烈士",
    bio: "长沙板仓人，毛泽东恩师杨昌济之女。1920年冬与毛泽东结婚，1921年入党，随毛泽东辗转上海、韶山、广州、武汉开展工人运动与农民运动。1927年秋收起义爆发后与毛泽东诀别，独自携三个儿子回板仓坚持地下斗争。1930年10月被何键部逮捕，面对“登报声明与毛泽东脱离夫妻关系即可活命”的条件，她断然拒绝：“死不足惜，惟愿润之革命早日成功。”11月14日就义于长沙识字岭，年29岁。1982年修缮其故居时，墙缝中发现她生前藏匿的手稿数篇，情深辞切。",
    events: []
  },
  "hezhizhen": {
    name: "贺子珍", life: "1909—1984", faction: "ccp", title: "井冈山第一位女党员",
    bio: "江西永新人，1926年入党，参加永新暴动后随兄贺敏学上井冈山，是井冈山第一位女党员。1928年与毛泽东结婚，此后伴其度过井冈山、瑞金与长征最艰苦的岁月，长征途中为掩护伤员身负重伤，体内终生留有弹片。1937年冬赴苏联治病、学习，历经丧子之痛与卫国战争艰辛，1947年归国，先后在哈尔滨、杭州、上海居住。1984年4月病逝于上海，骨灰安放于北京八宝山革命公墓。",
    events: ["jinggangshan", "changzheng"]
  },
  "jiangqing_mao": {
    name: "江青", life: "1914—1991", faction: "ccp", title: "毛泽东夫人 · “四人帮”之首",
    bio: "山东诸城人，原名李云鹤。1930年代为上海影剧界演员（艺名蓝苹），1937年经西安赴延安，入抗日军政大学学习，1938年与毛泽东结婚。建国后曾任中共中央宣传部电影处处长。“文化大革命”中任中央文革小组副组长，与张春桥、姚文元、王洪文结成“四人帮”，煽动极左路线、参与迫害大批干部群众。1976年10月被隔离审查，1977年被开除党籍，1981年被最高人民法院特别法庭判处死刑缓期二年执行，后依法减为无期徒刑。1991年5月14日在北京保外就医期间自杀身亡。",
    events: []
  },
  "maoanying": {
    name: "毛岸英", life: "1922—1950", faction: "ccp", title: "志愿军烈士 · 毛泽东长子",
    bio: "生于长沙清水塘，杨开慧长子。1930年目睹母亲就义，与弟弟岸青流落上海五年，当过学徒、捡过破烂、推过黄包车。1936年经组织安排赴法国转抵苏联，入莫斯科国际儿童院，后进伏龙芝军事学院，苏德战争后期随苏军反攻至柏林近郊。1946年归国，在延安拜劳动英雄吴满有为师学农，后参加土改。1950年10月参加中国人民志愿军，任司令部俄语翻译兼机要参谋；11月25日美军空袭志愿军司令部驻地大榆洞，他冲回作战室抢救电报，牺牲于汽油弹火海，年28岁，安葬于朝鲜桧仓中国人民志愿军烈士陵园。毛泽东闻讯久久无言：“谁叫他是毛泽东的儿子呢。”",
    events: ["kangmei-yuanchao"]
  }
});

EVENTS.push(
  { id: "caopi-chanhan", year: 220, date: "220年", category: "politics", p: 5,
    title: "曹丕代汉建魏",
    desc: "220年正月曹操病逝于洛阳，曹丕继魏王位。同年十月，汉献帝“禅让”帝位，曹丕三让而后受，于繁阳筑坛即皇帝位，国号魏，改元黄初——延续405年的汉王朝名实俱亡，三国时代正式开始。刘备次年称帝续汉统，孙权8年后称帝。",
    result: "“禅让”至此沦为篡位的形式化表演，此后魏晋南北朝王朝更迭皆循此例。曹丕还采纳陈群九品中正制，门阀政治自此发端，深刻影响了此后三百年的中国政治生态。",
    people: ["caopi"] },
  { id: "junjichu", year: 1729, date: "1729年前后", category: "politics", p: 10,
    title: "军机处与摊丁入亩",
    desc: "雍正为迅速处理西北军务，在隆宗门内设立军机处——军机大臣“跪受笔录”，皇权空前集中，延续近两百年的军机制度由此确立。同期在全国推行摊丁入亩：将康熙五十年的人丁税固定数额摊入田赋一并征收，从此“滋生人丁，永不加赋”落到实处；又行火耗归公、养廉银整顿吏治，改土归流整顿西南。",
    result: "军机处强化了皇权，摊丁入亩废除了延续两千年的人头税，无地少地的农民负担大减，人口随之大增——乾隆末年全国人口突破三亿。清朝中前期的财政与行政效率，在此打下根基。",
    people: ["yongzheng"] }
);

