    bio: "秦惠文王之子，19岁即位，前期宣太后与魏冉专权，41岁亲政后用范雎“远交近攻”之策。在位五十六年：伊阙之战白起歼韩魏联军24万，鄢郢之战破楚都，长平之战坑赵卒四十余万，灭西周国迁九鼎——秦统一天下的基础实奠定于昭王之世。李冰即在昭王末年任蜀郡守修建都江堰。",
