    bio: "四川云阳人，1938年入党，曾任重庆市委委员。1943年与江竹筠假扮夫妻开展地下工作，1945年经组织批准结为真正的夫妻。1947年赴下川东领导武装斗争，1948年1月率游击队突围时中弹牺牲，头颅被挂在城门示众。江竹筠路过时说：“我来看你来了。”",
    events: ["jiangjie"]
