    bio: "河北丰宁人，董存瑞生前所在班的班长。1948年5月25日隆化战斗中，他掩护董存瑞冲至桥型暗堡下，亲眼目睹董存瑞托起炸药包高呼“为了新中国，前进”，是这一壮举唯一的近距离见证者。此后终生宣讲董存瑞事迹，晚年任董存瑞烈士陵园名誉园长。",
