    bio: "苏州吴县人，两岁丧父随母改嫁，苦学及第。戍边西北抵御西夏，“军中有一范，西贼闻之惊破胆”。1043年主持庆历新政，明黜陟、抑侥幸、精贡举，旋即失败。1046年于邓州写《岳阳楼记》：“先天下之忧而忧，后天下之乐而乐”，为中国士大夫精神立下千年标尺。设义庄赡养族人，开慈善先河。",
