    bio: "大都人，号已斋叟，“生而倜傥，博学能文，滑稽多智”。一生创作杂剧六十余种，现存十八种，《窦娥冤》以“六月飞雪”控诉冤狱，是中国古典悲剧巅峰；《救风尘》《单刀会》各擅胜场。自喻“蒸不烂、煮不熟、捶不匾、炒不爆、响珰珰一粒铜豌豆”。元曲与唐诗宋词并峙，关汉卿为关白马郑“元曲四大家”之首。",
    events: ["yuan-wenhua"]
