    result: "松江成为全国棉纺中心，“松郡棉布，衣被天下”，棉布自此逐步取代丝麻成为百姓衣被主流；元曲与唐诗宋词并称，塑造了此后六百年中国通俗文学与戏曲的底色。1980年黄道婆形象入选中国邮政邮票。",
