    bio: "渤海蓨人，少落魄，曾乞食梁宋。50岁前躬耕不遇，《别董大》“莫愁前路无知己，天下谁人不识君”写于最穷困时。安史乱中拜左拾遗、淮南节度使，讨永王璘；广德年代崔光远解长安、剑南之围，封渤海县侯——唐代诗人中功业最盛者，“有唐已来，诗人之达者，唯适而已”。与岑参并称“高岑”。",
