    bio: "曲阜人，孔子六十四代孙。康熙二十三年（1684）康熙南巡祭孔，孔尚任御前讲《大学》受赏识，破格授国子监博士；淮扬治河三年，遍交明朝遗民。康熙三十八年（1699）《桃花扇》成——「借离合之情，写兴亡之感」，以侯方域、李香君爱情写南明覆灭，「王公荐绅莫不借钞」。次年罢官，学界多疑与此剧触怒当局有关。「南洪北孔」为清初剧坛双璧。",
    events: []
