    bio: "名沃尧，字趼人，号我佛山人，佛山人。十八岁赴上海谋生，任报刊编辑，主笔《月月小说》。1903年起连载《二十年目睹之怪现状》——借「九死一生」二十年所见，写官场、商场、洋场种种丑态，与《官场现形记》《老残游记》《孽海花》并称清末谴责小说四大名著。另著《痛史》《九命奇冤》。四十四岁卒于上海。",
